namespace RisingLands;
public sealed class TradeTransaction {public bool NativeValuation{get;set;}public bool Session{get;set;}public int SessionId{get;set;}public int Sympathy{get;set;}public int Relation{get;set;}public int Market{get;set;}public int Partner{get;set;}public int Owner{get;set;}public int[] Given{get;set;}=new int[3];public int[] Received{get;set;}=new int[3];public long Tick{get;set;}}
public sealed class TradeContact {public int Messenger{get;set;}public int Market{get;set;}public int Cell{get;set;}public bool Arrived{get;set;}}
public sealed partial class Simulation {
 // Modern save vectors retain food/rock/parts; original market vectors are parts/food/rock.
 public static int MarketResource(int kind,int owner=0)=>kind*4+owner;
 public IEnumerable<Building> MarketPartners(int market)=>World.Buildings.Where(b=>b.Type==16&&b.Owner is >=1 and <=3&&Inhabited(b)&&Special.Contacts.Any(c=>c.Market==b.Slot&&c.Arrived&&World.Units.Any(a=>a.Slot==c.Messenger&&a.Health>0&&a.Type==10)));
 public bool ContactMarket(Actor messenger,int slot)=>SendMessenger(messenger,slot);
 bool LegacyContactMarket(Actor messenger,int slot){var b=World.Buildings.FirstOrDefault(b=>b.Slot==slot&&b.Type==16&&b.Owner is >=1 and <=3);if(messenger.Type!=10||messenger.Owner!=0||!VisualCatalog.Visible(messenger)||b==null||!BuildingInSight(b)||!Inhabited(b))return false;foreach(int cell in BuildingInteractionCells(b)){if(!Order(messenger,cell&255,cell>>8,true))continue;ClearOrdersExceptRoute(messenger);Special.Contacts.RemoveAll(c=>c.Messenger==messenger.Slot);Special.Contacts.Add(new(){Messenger=messenger.Slot,Market=slot,Cell=cell});return true;}return false;}
 void ClearOrdersExceptRoute(Actor a)=>StopExceptTravel(a);
 void TradeContactStep(){foreach(var c in Special.Contacts.Where(c=>!c.Arrived)){var a=World.Units.FirstOrDefault(a=>a.Slot==c.Messenger);var b=World.Buildings.FirstOrDefault(b=>b.Slot==c.Market);if(a!=null&&!Feeding(a)&&b!=null&&a.Type==10&&a.Health>0&&ReachBuildingInteraction(a,b,c.Cell))c.Arrived=true;}}
 public int TradeScore(int[] give,int[] take,int sympathy=0,int relation=0){if(give.Length!=3||take.Length!=3||give.Any(x=>x<0)||take.Any(x=>x<0))return 0;long offer=Enumerable.Range(0,3).Sum(i=>(long)give[i]*SpecialData.ResourceValues[i==0?1:i==1?2:0]);long request=Enumerable.Range(0,3).Sum(i=>(long)take[i]*SpecialData.ResourceValues[i==0?1:i==1?2:0]);long valued=offer*(100+sympathy+relation*40-20)/100;return request==0?valued>0?200:0:(int)Math.Clamp(valued*100/request,0,ushort.MaxValue);}
 static int LegacyTradeScore(int[] give,int[] take){long offer=Enumerable.Range(0,3).Sum(i=>(long)give[i]*SpecialData.ResourceValues[i]),request=Enumerable.Range(0,3).Sum(i=>(long)take[i]*SpecialData.ResourceValues[i]);return request==0?0:(int)(offer*80/100*100/request);}
 public bool CanTrade(int market,int partner,int[] give,int[] take){var b=World.Buildings.FirstOrDefault(b=>b.Slot==market&&b.Type==16&&b.Owner==0&&Inhabited(b));var other=MarketPartners(market).FirstOrDefault(b=>b.Slot==partner);if(b==null||other==null||Special.Trades.Count>=10000||give.Length!=3||take.Length!=3||give.Any(x=>x<0||x>65535)||take.Any(x=>x<0||x>65535)||give.Sum()==0||take.Sum()==0||TradeScore(give,take)<100)return false;for(int i=0;i<3;i++){int a=World.Resources[MarketResource(i)],o=World.Resources[MarketResource(i,other.Owner)];if(a<give[i]||o<take[i]||a-give[i]+take[i]>65535||o-take[i]+give[i]>65535)return false;}return true;}
 public bool Trade(int market,int partner,int[] give,int[] take){if(!CanTrade(market,partner,give,take))return false;int owner=World.Buildings.First(b=>b.Slot==partner).Owner;for(int i=0;i<3;i++){int a=MarketResource(i),b=MarketResource(i,owner);World.Resources[a]=(ushort)(World.Resources[a]-give[i]+take[i]);World.Resources[b]=(ushort)(World.Resources[b]-take[i]+give[i]);}Special.Trades.Add(new(){NativeValuation=true,Market=market,Partner=partner,Owner=owner,Given=(int[])give.Clone(),Received=(int[])take.Clone(),Tick=Tick});return true;}
 static long TradeNet(Save s,int kind,int owner){long total=0;foreach(var t in s.Special?.Trades??new()){if(owner==0)total+=t.Received[kind]-t.Given[kind];else if(owner==t.Owner)total+=t.Given[kind]-t.Received[kind];}return total;}
 void ValidateTrades(Save s,SpecialState state){
  if(state.Trades.Count>10000||state.Contacts.Count>1000||state.Contacts.Select(c=>c.Messenger).Distinct().Count()!=state.Contacts.Count)throw new InvalidDataException("Invalid trade count");var buildings=InitialBuildings.Concat(s.Constructions.Where(Complete).Select(c=>new Building(c.Id,c.Type,c.Owner,c.Cell))).ToArray();
  foreach(var t in state.Trades)if(t.Owner is <1 or >3||t.Given==null||t.Received==null||t.Given.Length!=3||t.Received.Length!=3||t.Given.Concat(t.Received).Any(x=>x<0||x>65535)||!t.Session&&(t.Given.Sum()==0||t.Received.Sum()==0||(t.NativeValuation?TradeScore(t.Given,t.Received):LegacyTradeScore(t.Given,t.Received))<100)||t.Session&&(t.Sympathy is < -60 or >100||t.Relation is <0 or >1)||t.Tick<0||t.Tick>s.Tick||!buildings.Any(b=>b.Slot==t.Market&&b.Type==16&&b.Owner==0)||!buildings.Any(b=>b.Slot==t.Partner&&b.Type==16&&b.Owner==t.Owner))throw new InvalidDataException("Invalid trade record");
  foreach(var c in state.Contacts)if(!s.Units.Any(a=>a.Slot==c.Messenger&&a.Type==10)||!buildings.Any(b=>b.Slot==c.Market&&b.Type==16&&b.Owner is >=1 and <=3&&(state.Negotiations.Any(n=>n.Messenger==c.Messenger)||ValidBuildingArrivalCells(b).Contains(c.Cell))))throw new InvalidDataException("Invalid market contact");
 }
}
